// ResetIcon.h -- the holster editor's reset-arrow icon (HW-UX3 L0b): two embedded 32x32 textures, hse_reset (teal) and hse_reset_hi (gold hover),
// registered through EmbedTex.h and handed out as pooled GUI image handles (same pattern as HudKit.h / LevelUpUi.h).
//
// Pixels live in ../_shared_src/ResetIconTex.inc (GENERATED by scripts/gen_reset_icon.py). Usage: set embtex::g_log, call resetIconEnsure() once
// while building the page (idempotent, Steam only), embtex::heal() every UI tick, then guikit::setButtonFill(btn, resetIconImage(false),
// resetIconImage(true)) (GuiKit.h). resetIconImage returns nullptr until the texture exists (a failed lookup is not pooled: it retries), so
// callers keep their "R" text until both handles are non-null.
// setButtonFill returns false when the mod-config entry fell back to a LABEL clone (button_clone=0 or the clone failed); callers then try
// guikit::setFill on the control as the second path. resetIconApply() below is that order: button first, label second, false if both fail. embtex::MaxTex (16) must hold this mod's other textures plus these 2.
#pragma once
#include "EmbedTex.h"
#include "GuiKit.h"

namespace hse {

namespace reseticon_detail {
#include "ResetIconTex.inc"   // kResetIconTex, kResetIconHiTex, kResetTex[], kResetTexCount
}

constexpr int kResetIconSize = 32;   // source texture is 32x32 (the reset slot is at most ~a third of a row; HseView.h)

inline const embtex::Tex* resetIconTextures() { return reseticon_detail::kResetTex; }
inline int resetIconTextureCount() { return static_cast<int>(reseticon_detail::kResetTexCount); }
inline const char* resetIconResref(bool hi) { return reseticon_detail::kResetTex[hi ? 1 : 0].resref; }

// Create + fill + queue both textures (EmbedTex ensure(): idempotent, Steam-only; false on any other exe or when an engine call fails).
inline bool resetIconEnsure() { return embtex::ensure(reseticon_detail::kResetTex, static_cast<int>(reseticon_detail::kResetTexCount)); }

// Pooled GUI image handle of the normal (hi = false) or hover (hi = true) arrow; nullptr until the texture exists. Never released.
inline void* resetIconImage(bool hi) {
    static void* cache[2] = {};
    const int i = hi ? 1 : 0;
    if (!cache[i]) cache[i] = guikit::imageForRetry(reseticon_detail::kResetTex[i].resref);
    return cache[i];
}

// Apply the reset icon to one control with the two-path order: fillBtn() (guikit::setButtonFill) first; when it returns false (label clone
// fallback) fillLabel() (guikit::setFill) second. True when either path took; false when both failed (keep the "R" text). Null callbacks fail.
inline bool resetIconApply(bool (*fillBtn)(), bool (*fillLabel)()) {
    if (fillBtn && fillBtn()) return true;
    return fillLabel && fillLabel();
}

}  // namespace hse
